      typeof activity.payload === "object" && activity.payload !== null
        ? (activity.payload as Record<string, unknown>)
        : null;
    const used = asInt(payload?.usedTokens);
    if (used === null) continue;
    usedTokens = used;
    maxTokens = asInt(payload?.maxTokens);
  }
